1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { authenticateApiToken, tokenHasScope } from "@/lib/api-auth";
4	
5	export const dynamic = "force-dynamic";
6	
7	/**
8	 * GET /api/v1/servers
9	 * Bearer-token authenticated. Returns the caller's servers.
10	 *
11	 *   Authorization: Bearer nxe_<prefix>_<random>
12	 */
13	export async function GET(req: Request) {
14	  const auth = await authenticateApiToken(req);
15	  if (!auth.ok) {
16	    return NextResponse.json({ error: auth.error }, { status: auth.status });
17	  }
18	
19	  // Enforce read scope. Legacy tokens (no scopes recorded) remain full-access.
20	  if (!tokenHasScope(auth, "servers:read")) {
21	    return NextResponse.json(
22	      { error: "Token missing required scope: servers:read" },
23	      { status: 403 }
24	    );
25	  }
26	
27	  const servers = await db.server.findMany({
28	    where: { userId: auth.user.id },
29	    orderBy: { createdAt: "desc" },
30	    select: { id: true, name: true, status: true, ipAddress: true },
31	  });
32	
33	  return NextResponse.json({
34	    servers: servers.map((s) => ({
35	      id: s.id,
36	      name: s.name,
37	      status: s.status,
38	      ip: s.ipAddress,
39	    })),
40	  });
41	}
42

1	import { NextRequest, NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { db } from "@/lib/db";
4	import { invoiceBranding, renderInvoiceHTML } from "@/lib/invoices";
5	
6	/**
7	 * Returns the branded, print-ready invoice as standalone HTML.
8	 *
9	 * NOTE: There is no PDF library installed and we cannot add dependencies, so
10	 * this is the pragmatic approach — the page ships with a print-optimised
11	 * stylesheet and a "Print / Save as PDF" button; the browser's Print → Save
12	 * as PDF produces the downloadable document.
13	 */
14	export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
15	  const { id } = await params;
16	  const user = await currentUser();
17	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
18	
19	  const invoice = await db.invoice.findUnique({
20	    where: { id },
21	    include: { user: { select: { name: true, email: true } } },
22	  });
23	  if (!invoice) return NextResponse.json({ error: "not found" }, { status: 404 });
24	
25	  const isOwner = invoice.userId === user.id;
26	  const isAdmin = user.role === "ADMIN";
27	  if (!isOwner && !isAdmin) {
28	    return NextResponse.json({ error: "forbidden" }, { status: 403 });
29	  }
30	
31	  // The downloaded document must carry the same identifier the dashboard showed the
32	  // customer — an accountant reconciling "INV-00012" against a file headed "#00012" has
33	  // to guess whether they are the same invoice. This is also the one render site where
34	  // `company_legal_name` / `company_address` become visible.
35	  const html = renderInvoiceHTML(invoice, invoice.user, await invoiceBranding());
36	  return new NextResponse(html, {
37	    status: 200,
38	    headers: {
39	      "Content-Type": "text/html; charset=utf-8",
40	      "Cache-Control": "private, no-store",
41	    },
42	  });
43	}
