1	import { NextRequest, NextResponse } from "next/server";
2	import { stripe, stripeConfigured } from "@/lib/stripe";
3	import { fulfilCheckoutSession } from "@/lib/fulfil-checkout";
4	
5	export async function POST(req: NextRequest) {
6	  if (!stripeConfigured() || !process.env.STRIPE_WEBHOOK_SECRET) {
7	    return NextResponse.json({ error: "not configured" }, { status: 400 });
8	  }
9	  const sig = req.headers.get("stripe-signature");
10	  if (!sig) return NextResponse.json({ error: "missing signature" }, { status: 400 });
11	  const raw = await req.text();
12	
13	  let event;
14	  try {
15	    event = stripe().webhooks.constructEvent(raw, sig, process.env.STRIPE_WEBHOOK_SECRET);
16	  } catch {
17	    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
18	  }
19	
20	  if (event.type === "checkout.session.completed") {
21	    const session = event.data.object as { id: string };
22	    // FULFIL, don't just credit. This used to call `creditCheckoutSession` and
23	    // throw the result away, which meant the webhook credited the wallet and then
24	    // — by winning the race — caused the success-redirect to see `credited: false`
25	    // and skip provisioning entirely. The webhook is the reliable signal (the
26	    // redirect may never happen at all), so it must be able to fulfil on its own.
27	    // `fulfilCheckoutSession` is idempotent via UNIQUE(FulfilledSession), so the
28	    // two callers racing is safe: exactly one does the work.
29	    //
30	    // Errors are swallowed deliberately — returning non-2xx makes Stripe retry the
31	    // event, and the failure is already recorded on the FulfilledSession row and
32	    // surfaced to the customer.
33	    try {
34	      await fulfilCheckoutSession(session.id);
35	    } catch (e) {
36	      console.error("[stripe-webhook] fulfil failed", session.id, e);
37	    }
38	  }
39	
40	  return NextResponse.json({ received: true });
41	}
42

1	import { NextRequest, NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { stripe, stripeConfigured } from "@/lib/stripe";
4	import { getSettingInt } from "@/lib/settings";
5	
6	/** Set by `components/customer/CouponField`; read by `topUp`'s demo gateway only. */
7	const COUPON_COOKIE = "nxeon_coupon";
8	
9	export async function POST(req: NextRequest) {
10	  const user = await currentUser();
11	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
12	  if (!stripeConfigured()) {
13	    return NextResponse.json({ error: "Stripe is not configured yet" }, { status: 400 });
14	  }
15	  const { amount } = await req.json().catch(() => ({}));
16	  const dollars = Number(amount);
17	  if (!Number.isFinite(dollars) || dollars > 5000) {
18	    return NextResponse.json({ error: "Amount must be $5–$5000" }, { status: 400 });
19	  }
20	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
21	  const minTopup = await getSettingInt("min_topup_cents", 500);
22	  if (Math.round(dollars * 100) < minTopup) {
23	    return NextResponse.json(
24	      { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}` },
25	      { status: 400 },
26	    );
27	  }
28	
29	  // A promo code must never be silently dropped at the moment money moves.
30	  //
31	  // `CouponField` stores an accepted code in this cookie for an hour, and the ONLY
32	  // reader is the demo gateway in `topUp`. This route charges the card and
33	  // `creditCheckoutSession` credits `session.amount_total` verbatim, so a bonus
34	  // simply cannot be added here — and Stripe's own `discounts` /
35	  // `allow_promotion_codes` are the wrong instrument for a wallet top-up: they
36	  // reduce `amount_total`, which reduces the credit by the same cents, leaving the
37	  // customer exactly where they started. So a cookie surviving into this path
38	  // (e.g. Stripe was configured after the code was accepted) would mean paying
39	  // full price with a code the UI said was applied — the audit's finding #8.
40	  //
41	  // Refuse, say why, and clear the cookie in the same response so the immediate
42	  // retry succeeds. Nothing has been charged at this point: no session exists yet.
43	  const staleCoupon = req.cookies.get(COUPON_COOKIE)?.value?.trim();
44	  if (staleCoupon) {
45	    const shown = staleCoupon.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32).toUpperCase();
46	    const res = NextResponse.json(
47	      {
48	        error: `Promo code ${shown || "on this account"} can’t be applied to a card payment. We’ve removed it — press Add funds again to continue without it.`,
49	      },
50	      { status: 400 },
51	    );
52	    res.cookies.set({ name: COUPON_COOKIE, value: "", path: "/", maxAge: 0 });
53	    return res;
54	  }
55	
56	  const base = process.env.APP_URL ?? "http://localhost:3000";
57	  const session = await stripe().checkout.sessions.create({
58	    mode: "payment",
59	    customer_email: user.email,
60	    line_items: [
61	      {
62	        price_data: {
63	          currency: "usd",
64	          product_data: { name: "Nxeon wallet credit" },
65	          unit_amount: Math.round(dollars * 100),
66	        },
67	        quantity: 1,
68	      },
69	    ],
70	    metadata: { nxeonUserId: user.id },
71	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
72	    cancel_url: `${base}/dashboard/billing?canceled=1`,
73	  });
