5	/**
6	 * Checkout success-redirect target.
7	 *
8	 * This route no longer OWNS fulfilment — it asks the shared, idempotent
9	 * `fulfilCheckoutSession` to do it and follows whatever redirect comes back. The
10	 * webhook calls the identical function, so whichever arrives first fulfils and the
11	 * other is a harmless no-op.
12	 *
13	 * Until 2026-07-25 the logic lived here and was gated on whether the wallet credit
14	 * was inserted by THIS request — which made a browser redirect the fulfilment
15	 * trigger. If the webhook won the race, or the customer simply closed the tab
16	 * before this URL resolved, the payment was captured and nothing was provisioned:
17	 * no server, no error, no notification. Stripe's own guidance is explicit that a
18	 * redirect must never be what triggers fulfilment.
19	 */
20	export async function GET(req: NextRequest) {
21	  const base = process.env.APP_URL ?? "";
22	  const sessionId = req.nextUrl.searchParams.get("session_id");
23	  if (!stripeConfigured() || !sessionId) {
24	    return NextResponse.redirect(`${base}/dashboard/billing`);
25	  }
26	  try {
27	    const result = await fulfilCheckoutSession(sessionId, base);
28	    return NextResponse.redirect(result.redirect);
29	  } catch {
30	    // Never strand the customer on an error page: the webhook is an independent
31	    // backstop and will fulfil this session regardless of what happened here.
32	    return NextResponse.redirect(`${base}/dashboard/billing?pending=1`);
33	  }
34	}
