1	import { NextRequest, NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { getGuestDiskUsage, pve, node as defaultNode, pveFor } from "@/lib/proxmox";
5	import { effectiveDiskGB } from "@/lib/extra-disk";
6	
7	export const dynamic = "force-dynamic";
8	
9	type Pt = { time: number; disk: number | null; maxdisk: number | null };
10	
11	// Chart timeframe → lookback window (ms). Matches DiskUsageChart's 24h/7d/30d.
12	const WINDOW_MS: Record<string, number> = {
13	  day: 24 * 60 * 60_000,
14	  week: 7 * 24 * 60 * 60_000,
15	  month: 30 * 24 * 60 * 60_000,
16	};
17	
18	/**
19	 * Real in-guest disk usage for a server the current user owns.
20	 *
21	 * Data comes from ServerDiskSample (collected by the worker via the QEMU guest
22	 * agent, since Proxmox RRD reports disk=0 for QEMU VMs) for the requested
23	 * window, plus a fresh live get-fsinfo reading appended as the current point.
24	 * Falls back to the latest stored sample when the live call isn't ready, and to
25	 * an empty series (chart shows the "not reporting" note) only when neither the
26	 * agent nor any sample yields anything.
27	 */
28	export async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
29	  const { id } = await ctx.params;
30	  const user = await currentUser();
31	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
32	
33	  const tf = req.nextUrl.searchParams.get("tf") ?? "day";
34	
35	  const server = await db.server.findUnique({
36	    where: { id },
37	    include: { node: true, plan: true },
38	  });
39	  if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
40	    return NextResponse.json({ error: "not found" }, { status: 404 });
41	  }
42	
43	  // Effective disk (plan + purchased extra) — a server that bought extra storage
44	  // must not be charted against its plan's smaller allowance.
45	  const planTotalBytes = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB) * 1024 ** 3;
46	  const since = new Date(Date.now() - (WINDOW_MS[tf] ?? WINDOW_MS.day));
47	
48	  // 1. Stored history for the window.
49	  let samples: { ts: Date; usedBytes: bigint; totalBytes: bigint }[] = [];
50	  try {
51	    samples = await db.serverDiskSample.findMany({
52	      where: { serverId: id, ts: { gte: since } },
53	      orderBy: { ts: "asc" },
54	      select: { ts: true, usedBytes: true, totalBytes: true },
55	    });
56	  } catch {
57	    samples = [];
58	  }
59	
60	  const data: Pt[] = samples.map((s) => ({
61	    time: Math.floor(s.ts.getTime() / 1000),
62	    disk: Number(s.usedBytes),
63	    maxdisk: Number(s.totalBytes),
64	  }));
65	
66	  // 2. Fresh live reading for the current point (best-effort).
67	  let current: { usedBytes: number; totalBytes: number } | null = null;
68	  try {
69	    const client = server.node
70	      ? pveFor({
71	          apiUrl: server.node.apiUrl,
72	          pveNode: server.node.pveNode,
73	          tokenId: server.node.tokenId,
74	          tokenSecret: server.node.tokenSecret,
75	        })
76	      : pve;
77	    const pnode = server.node?.pveNode ?? defaultNode;
78	    current = await getGuestDiskUsage(client, pnode, server.vmid, planTotalBytes);
79	  } catch {
80	    current = null;
81	  }
82	
83	  // Fall back to the newest stored sample when the live call isn't ready.
84	  if (!current && samples.length > 0) {
85	    const last = samples[samples.length - 1];
86	    current = { usedBytes: Number(last.usedBytes), totalBytes: Number(last.totalBytes) };
87	  }
88	
89	  // Append the current reading so the chart always shows the freshest value
90	  // (and isn't empty when there are no samples yet but the agent responds).
91	  if (current) {
92	    data.push({
93	      time: Math.floor(Date.now() / 1000),
94	      disk: current.usedBytes,
95	      maxdisk: current.totalBytes,
96	    });
97	  }
98	
99	  // Prefer the fsinfo/sample total; fall back to the plan's provisioned size.
100	  const totalBytes =
101	    current?.totalBytes ??
102	    (samples.length > 0 ? Number(samples[samples.length - 1].totalBytes) : planTotalBytes);
103	
104	  return NextResponse.json({ data, planTotalBytes: totalBytes });
105	}
