18	      if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
19	        return NextResponse.json({ error: "not found" }, { status: 404 });
20	      }
21	      // Query the node the VM actually lives on — vmids collide across nodes, so
22	      // defaulting to the primary would leak another tenant's same-numbered VM.
23	      const conn = server.node
24	        ? pveFor({
25	            apiUrl: server.node.apiUrl,
26	            pveNode: server.node.pveNode,
27	            tokenId: server.node.tokenId,
28	            tokenSecret: server.node.tokenSecret,
29	          })
30	        : undefined;
31	      const data = await vmRrd(server.vmid, timeframe, conn);
32	      return NextResponse.json({ data });
33	    }
34	    if (user.role !== "ADMIN") return NextResponse.json({ error: "forbidden" }, { status: 403 });
35	    const data = await nodeRrd(timeframe);
