1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { checkRateLimit } from "@/lib/rate-limit";
5	
6	export const runtime = "nodejs";
7	
8	/**
9	 * Public live-chat endpoint used by <ChatWidget/>.
10	 *
11	 * POST /api/chat  — start or continue a conversation for a visitorId.
12	 * GET  /api/chat?visitorId=…  — poll the visitor's open conversation.
13	 *
14	 * Everything is scoped strictly by the client-supplied `visitorId`; we never
15	 * return another visitor's data. Signed-in customers additionally get their
16	 * `userId` stamped on the conversation. Unauthenticated + write-heavy, so the
17	 * POST path is rate-limited per IP.
18	 */
19	
20	/** First hop of x-forwarded-for is the real client (nginx appends downstream). */
21	function clientIp(req: Request): string {
22	  const xff = req.headers.get("x-forwarded-for") ?? "";
23	  const first = xff.split(",")[0]?.trim();
24	  return first || "unknown";
25	}
26	
27	function clip(v: unknown, max: number): string | null {
28	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
29	}
30	
31	type AttachmentRow = { id: string; mime: string; sizeBytes: number } | null;
32	
33	function serialize(convo: {
34	  id: string;
35	  status: string;
36	  name: string | null;
37	  email: string | null;
38	  messages: {
39	    id: string;
40	    sender: string;
41	    body: string;
42	    createdAt: Date;
43	    attachment?: AttachmentRow;
44	  }[];
45	}) {
46	  return {
47	    conversation: {
48	      id: convo.id,
49	      status: convo.status,
50	      name: convo.name,
51	      email: convo.email,
52	    },
53	    messages: convo.messages.map((m) => ({
54	      id: m.id,
55	      sender: m.sender,
56	      body: m.body,
57	      createdAt: m.createdAt.toISOString(),
58	      attachment: m.attachment
59	        ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
60	        : null,
61	    })),
62	  };
63	}
64	
65	export async function POST(req: Request) {
66	  const rl = checkRateLimit(`chat:${clientIp(req)}`, { max: 30, windowMs: 60_000 });
67	  if (!rl.ok) {
68	    return NextResponse.json(
69	      { error: "Too many messages. Please slow down." },
70	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
71	    );
72	  }
73	
74	  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
75	  const visitorId = clip(raw.visitorId, 100);
76	  const body = clip(raw.body, 5000);
77	  const name = clip(raw.name, 120);
78	  const email = clip(raw.email, 200);
79	
80	  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
81	  if (!body) return NextResponse.json({ error: "Message cannot be empty." }, { status: 400 });
82	
83	  const user = await currentUser();
84	
85	  // Continue the visitor's existing open conversation, else start a new one.
86	  let convo = await db.chatConversation.findFirst({
87	    where: { visitorId, status: "OPEN" },
88	    orderBy: { lastMessageAt: "desc" },
89	    select: { id: true, name: true, email: true },
90	  });
91	
92	  if (!convo) {
93	    convo = await db.chatConversation.create({
94	      data: {
95	        visitorId,
96	        userId: user?.id ?? null,
97	        name: name ?? user?.name ?? null,
98	        email: email ?? user?.email ?? null,
99	      },
100	      select: { id: true, name: true, email: true },
101	    });
102	  }
103	
104	  await db.$transaction([
105	    db.chatMessage.create({
106	      data: { conversationId: convo.id, sender: "visitor", body },
107	    }),
108	    db.chatConversation.update({
109	      where: { id: convo.id },
110	      data: {
111	        unreadForAgent: true,
112	        lastMessageAt: new Date(),
113	        // Backfill identity / link account if it arrives after creation.
114	        ...(user?.id ? { userId: user.id } : {}),
115	        ...(name && !convo.name ? { name } : {}),
116	        ...(email && !convo.email ? { email } : {}),
117	      },
118	    }),
119	  ]);
120	
121	  const full = await db.chatConversation.findUnique({
122	    where: { id: convo.id },
123	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
124	  });
125	  return NextResponse.json(serialize(full!));
126	}
127	
128	export async function GET(req: Request) {
129	  const url = new URL(req.url);
130	  const visitorId = clip(url.searchParams.get("visitorId"), 100);
131	  if (!visitorId) return NextResponse.json({ conversation: null, messages: [] });
132	
133	  const convo = await db.chatConversation.findFirst({
134	    where: { visitorId, status: "OPEN" },
135	    orderBy: { lastMessageAt: "desc" },
136	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
137	  });
138	
139	  if (!convo) return NextResponse.json({ conversation: null, messages: [] });
140	
141	  // Reading the thread clears the visitor-facing unread flag.
142	  if (convo.unreadForUser) {
143	    await db.chatConversation
144	      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
145	      .catch(() => {});
146	  }
147	
148	  return NextResponse.json(serialize(convo));
149	}
