17	 * the client-supplied `visitorId`, so a visitor can only ever attach to their
18	 * own thread. The image is validated by signature (not the client-declared
19	 * type) in lib/chat-attachment — SVG and non-images are rejected. Bytes live in
20	 * Postgres. Per-IP rate limited.
21	 */
22	
23	function clientIp(req: Request): string {
24	  const xff = req.headers.get("x-forwarded-for") ?? "";
25	  const first = xff.split(",")[0]?.trim();
26	  return first || "unknown";
27	}
28	
29	function clip(v: unknown, max: number): string | null {
30	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
31	}
32	
33	export async function POST(req: Request) {
34	  const rl = checkRateLimit(`chat-upload:${clientIp(req)}`, { max: 15, windowMs: 60_000 });
35	  if (!rl.ok) {
36	    return NextResponse.json(
37	      { error: "Too many uploads. Please slow down." },
38	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
39	    );
40	  }
41	
42	  let form: FormData;
43	  try {
44	    form = await req.formData();
45	  } catch {
46	    return NextResponse.json({ error: "Invalid upload." }, { status: 400 });
47	  }
48	
49	  const visitorId = clip(form.get("visitorId"), 100);
50	  const body = clip(form.get("body"), 5000) ?? "";
51	  const name = clip(form.get("name"), 120);
52	  const email = clip(form.get("email"), 200);
53	  const file = form.get("file");
54	
55	  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
56	  if (!(file instanceof File)) return NextResponse.json({ error: "No image provided." }, { status: 400 });
57	  // Cheap guard before buffering the whole body into memory.
58	  if (file.size > MAX_ATTACHMENT_BYTES) {
59	    return NextResponse.json({ error: "Image is larger than 5 MB." }, { status: 413 });
60	  }
61	
62	  const bytes = Buffer.from(await file.arrayBuffer());
63	  const check = validateImageBytes(bytes, file.type);
64	  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });
65	
66	  const user = await currentUser();
67	
68	  // Continue the visitor's existing open conversation, else start a new one.
69	  let convo = await db.chatConversation.findFirst({
