72	    select: { id: true, name: true, email: true },
73	  });
74	
75	  if (!convo) {
76	    convo = await db.chatConversation.create({
77	      data: {
78	        visitorId,
79	        userId: user?.id ?? null,
80	        name: name ?? user?.name ?? null,
81	        email: email ?? user?.email ?? null,
82	      },
83	      select: { id: true, name: true, email: true },
84	    });
85	  }
86	
87	  const convoId = convo.id;
88	  await db.$transaction(async (tx) => {
89	    const msg = await tx.chatMessage.create({
90	      data: { conversationId: convoId, sender: "visitor", body },
91	    });
92	    await tx.chatAttachment.create({
93	      data: {
94	        messageId: msg.id,
95	        mime: check.mime,
96	        sizeBytes: check.bytes.length,
97	        data: new Uint8Array(check.bytes),
98	      },
99	    });
100	    await tx.chatConversation.update({
101	      where: { id: convoId },
102	      data: {
103	        unreadForAgent: true,
104	        lastMessageAt: new Date(),
105	        ...(user?.id ? { userId: user.id } : {}),
106	        ...(name && !convo!.name ? { name } : {}),
107	        ...(email && !convo!.email ? { email } : {}),
108	      },
109	    });
110	  });
111	
112	  const full = await db.chatConversation.findUnique({
113	    where: { id: convoId },
114	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
115	  });
116	
117	  return NextResponse.json({
118	    conversation: full
119	      ? { id: full.id, status: full.status, name: full.name, email: full.email }
120	      : null,
121	    messages: (full?.messages ?? []).map((m) => ({
122	      id: m.id,
123	      sender: m.sender,
124	      body: m.body,
125	      createdAt: m.createdAt.toISOString(),
126	      attachment: m.attachment
