48	  // auto-add straight away so staging exercises the whole "connect → records
49	  // added" path without touching Cloudflare.
50	  if (SANDBOX) {
51	    await db.user.update({
52	      where: { id: user.id },
53	      data: {
54	        cloudflareTokenEnc: packCreds({
