4	import { extractHost, isPlausibleHost } from "@/lib/tools/net-guard";
5	
6	export const runtime = "nodejs";
7	export const dynamic = "force-dynamic";
8	
9	/**
10	 * DNS lookup — resolves A / AAAA / MX / TXT / NS / CNAME / SOA for a domain via
11	 * node:dns. Public DNS only (no connections are made to the target), but we still
12	 * validate the hostname and cap output. Rate-limited per IP.
13	 */
14	
15	const TIMEOUT_MS = 5000;
16	const TYPES = ["A", "AAAA", "MX", "TXT", "NS", "CNAME", "SOA"] as const;
17	type RecordType = (typeof TYPES)[number];
18	
19	function withTimeout<T>(p: Promise<T>): Promise<T> {
20	  return Promise.race([
21	    p,
22	    new Promise<T>((_, rej) => setTimeout(() => rej(new Error("timeout")), TIMEOUT_MS)),
23	  ]);
24	}
25	
26	export async function POST(req: Request) {
27	  const limited = toolRateLimit(req, "dns", { max: 30, windowMs: 60_000 });
28	  if (limited) return limited;
29	
30	  const raw = await readField(req, "domain");
31	  const host = extractHost(raw);
32	  if (!host || !isPlausibleHost(host)) return jsonError("Enter a valid domain name.");
33	  if (host === "localhost") return jsonError("That host is not allowed.");
34	
35	  const resolver = new Resolver({ timeout: TIMEOUT_MS, tries: 2 });
36	
37	  async function resolveType(type: RecordType): Promise<string[]> {
38	    try {
39	      switch (type) {
40	        case "A":
41	          return await withTimeout(resolver.resolve4(host!));
42	        case "AAAA":
43	          return await withTimeout(resolver.resolve6(host!));
44	        case "MX": {
45	          const mx = await withTimeout(resolver.resolveMx(host!));
46	          return mx
47	            .sort((a, b) => a.priority - b.priority)
48	            .map((r) => `${r.priority}\t${r.exchange}`);
49	        }
50	        case "TXT": {
51	          const txt = await withTimeout(resolver.resolveTxt(host!));
52	          return txt.map((chunks) => chunks.join(""));
53	        }
54	        case "NS":
55	          return await withTimeout(resolver.resolveNs(host!));
56	        case "CNAME":
57	          return await withTimeout(resolver.resolveCname(host!));
58	        case "SOA": {
59	          const soa = await withTimeout(resolver.resolveSoa(host!));
60	          return [
61	            `${soa.nsname} ${soa.hostmaster} serial=${soa.serial} refresh=${soa.refresh} retry=${soa.retry} expire=${soa.expire} minttl=${soa.minttl}`,
62	          ];
63	        }
64	      }
65	    } catch {
66	      return [];
67	    }
68	  }
69	
70	  try {
71	    const settled = await Promise.all(
72	      TYPES.map(async (t) => [t, (await resolveType(t)).slice(0, 100)] as const),
73	    );
74	    const records: Record<string, string[]> = {};
75	    for (const [t, vals] of settled) records[t] = vals;
76	    const total = Object.values(records).reduce((n, v) => n + v.length, 0);
77	    if (total === 0) return jsonError("No DNS records found (the domain may not exist).", 404);
78	    return NextResponse.json({ ok: true, host, records });
79	  } catch {
80	    return jsonError("DNS lookup failed.", 502);
81	  }
82	}
