20	function name(obj: unknown): string | null {
21	  if (!obj || typeof obj !== "object") return null;
22	  const rec = obj as Record<string, string>;
23	  return rec.CN || rec.O || (Object.values(rec).find((v) => typeof v === "string") ?? null);
24	}
25	
26	type ChainLink = { subject: string | null; issuer: string | null; validTo: string };
27	
28	function collectChain(cert: DetailedPeerCertificate): ChainLink[] {
29	  const out: ChainLink[] = [];
30	  const seen = new Set<string>();
31	  let cur: DetailedPeerCertificate | undefined = cert;
32	  while (cur && cur.fingerprint && !seen.has(cur.fingerprint)) {
33	    seen.add(cur.fingerprint);
34	    out.push({ subject: name(cur.subject), issuer: name(cur.issuer), validTo: cur.valid_to });
35	    if (cur.issuerCertificate && cur.issuerCertificate.fingerprint !== cur.fingerprint) {
36	      cur = cur.issuerCertificate;
37	    } else {
38	      break;
39	    }
40	    if (out.length >= 6) break;
41	  }
42	  return out;
43	}
