45	export async function POST(req: Request) {
46	  const limited = toolRateLimit(req, "ssl", { max: 20, windowMs: 60_000 });
47	  if (limited) return limited;
48	
49	  const raw = await readField(req, "host");
50	  const host = extractHost(raw);
51	  if (!host) return jsonError("Enter a valid host (e.g. example.com).");
52	
53	  try {
54	    const { host: servername, addresses } = await resolvePublicHost(host);
55	    const ip = addresses[0];
56	
57	    const result = await new Promise<{ cert: DetailedPeerCertificate; authorized: boolean; error: string | null; protocol: string | null }>(
58	      (resolve, reject) => {
59	        const socket = tls.connect(
60	          {
61	            host: ip,
62	            port: DEFAULT_PORT,
63	            servername,
64	            rejectUnauthorized: false,
65	            timeout: TIMEOUT_MS,
66	          },
67	          () => {
68	            const cert = socket.getPeerCertificate(true);
69	            const protocol = socket.getProtocol();
70	            const authorized = socket.authorized;
71	            const error = socket.authorizationError ? String(socket.authorizationError) : null;
72	            socket.destroy();
73	            if (!cert || Object.keys(cert).length === 0) {
74	              reject(new Error("No certificate was presented."));
75	              return;
76	            }
77	            resolve({ cert, authorized, error, protocol });
78	          },
79	        );
80	        socket.setTimeout(TIMEOUT_MS);
81	        socket.once("timeout", () => {
82	          socket.destroy();
83	          reject(new Error("Connection timed out."));
84	        });
85	        socket.once("error", (e) => {
86	          socket.destroy();
87	          reject(e);
88	        });
89	      },
90	    );
91	
92	    const cert: PeerCertificate = result.cert;
93	    const validFrom = new Date(cert.valid_from);
94	    const validTo = new Date(cert.valid_to);
95	    const now = Date.now();
96	    const daysToExpiry = Math.floor((validTo.getTime() - now) / 86_400_000);
