103	    return NextResponse.json({
104	      ok: true,
105	      host: servername,
106	      subject: name(cert.subject),
107	      issuer: name(cert.issuer),
108	      altNames: san,
109	      validFrom: validFrom.toISOString(),
110	      validTo: validTo.toISOString(),
111	      daysToExpiry,
112	      expired: daysToExpiry < 0,
113	      valid: result.authorized,
114	      validationError: result.error,
115	      protocol: result.protocol,
116	      serialNumber: cert.serialNumber ?? null,
117	      chain: collectChain(result.cert),
118	    });
119	  } catch (e) {
120	    if (e instanceof BlockedHostError) return jsonError(e.message, 403);
121	    const msg = e instanceof Error ? e.message : "SSL check failed.";
122	    return jsonError(`Could not complete TLS handshake: ${msg}`, 502);
123	  }
124	}
