26	function tryConnect(ip: string, port: number): Promise<{ open: boolean; latencyMs: number }> {
27	  return new Promise((resolve) => {
28	    const started = Date.now();
29	    const socket = new net.Socket();
30	    let settled = false;
31	    const finish = (open: boolean) => {
32	      if (settled) return;
33	      settled = true;
34	      socket.destroy();
35	      resolve({ open, latencyMs: Date.now() - started });
36	    };
37	    socket.setTimeout(TIMEOUT_MS);
38	    socket.once("connect", () => finish(true));
39	    socket.once("timeout", () => finish(false));
40	    socket.once("error", () => finish(false));
41	    socket.connect(port, ip);
42	  });
43	}
