9	/**
10	 * WHOIS lookup — raw TCP (port 43) WHOIS client with IANA referral following.
11	 *
12	 * We query whois.iana.org first, read the "refer:" / "whois:" server for the TLD,
13	 * then re-query that authoritative server. No third-party API, no dependency.
14	 * The WHOIS servers we connect to are a fixed allowlist (IANA + the referred host,
15	 * itself validated as a public hostname), timeouts ≤5s, output capped.
16	 */
17	
18	const PORT = 43;
19	const TIMEOUT_MS = 5000;
20	const MAX_BYTES = 64 * 1024;
21	
22	/** One raw WHOIS query to `server:43` for `query`. Resolves with the text body. */
23	function whoisQuery(server: string, query: string): Promise<string> {
24	  return new Promise((resolve, reject) => {
25	    const chunks: Buffer[] = [];
26	    let size = 0;
27	    const socket = net.createConnection({ host: server, port: PORT });
28	    socket.setTimeout(TIMEOUT_MS);
29	
30	    const done = (err?: Error) => {
31	      socket.destroy();
32	      if (err) reject(err);
33	      else resolve(Buffer.concat(chunks).toString("utf8"));
34	    };
35	
36	    socket.on("connect", () => socket.write(`${query}\r\n`));
37	    socket.on("data", (d) => {
38	      size += d.length;
39	      if (size > MAX_BYTES) {
40	        chunks.push(d.subarray(0, Math.max(0, MAX_BYTES - (size - d.length))));
41	        done();
42	        return;
43	      }
44	      chunks.push(d);
45	    });
46	    socket.on("end", () => done());
47	    socket.on("timeout", () => done(new Error("WHOIS server timed out.")));
48	    socket.on("error", (e) => done(e));
49	  });
50	}
51	
52	/** Pull a referral WHOIS server (refer:/whois:) out of an IANA response. */
53	function parseReferral(text: string): string | null {
54	  const m = text.match(/^(?:refer|whois):\s*([a-z0-9.-]+)\s*$/im);
55	  return m ? m[1].toLowerCase() : null;
56	}
57	
58	/** Extract a few well-known fields for the summary card. */
59	function summarize(text: string) {
60	  const grab = (labels: string[]): string[] => {
61	    const out: string[] = [];
62	    for (const line of text.split(/\r?\n/)) {
63	      const m = line.match(/^\s*([^:]+):\s*(.+?)\s*$/);
64	      if (!m) continue;
65	      const key = m[1].trim().toLowerCase();
66	      if (labels.some((l) => key === l || key.startsWith(l))) out.push(m[2].trim());
67	    }
68	    return [...new Set(out)];
69	  };
70	  return {
71	    registrar: grab(["registrar", "sponsoring registrar"])[0] ?? null,
72	    created: grab(["creation date", "created", "registered on", "registration time"])[0] ?? null,
73	    updated: grab(["updated date", "last updated", "last modified"])[0] ?? null,
74	    expires: grab(["registry expiry date", "expiration date", "expiry date", "expires", "expire"])[0] ?? null,
75	    status: grab(["domain status", "status"]).slice(0, 6),
76	    nameservers: grab(["name server", "nserver", "nameserver"]).map((n) => n.toLowerCase()).slice(0, 8),
77	  };
78	}
79	
80	export async function POST(req: Request) {
81	  const limited = toolRateLimit(req, "whois", { max: 15, windowMs: 60_000 });
82	  if (limited) return limited;
83	
84	  const raw = await readField(req, "domain");
85	  const host = extractHost(raw);
86	  if (!host || !isPlausibleHost(host) || net.isIP(host)) {
87	    return jsonError("Enter a valid domain name (e.g. example.com).");
88	  }
89	  if (host === "localhost" || !host.includes(".")) {
90	    return jsonError("Enter a fully-qualified domain name.");
91	  }
92	
93	  try {
94	    // 1) Ask IANA which server is authoritative for this TLD.
95	    const ianaText = await whoisQuery("whois.iana.org", host);
96	    const referral = parseReferral(ianaText);
97	
98	    let text = ianaText;
99	    let server = "whois.iana.org";
100	    // 2) Re-query the referred registry/registrar server if it's a valid public host.
101	    if (referral && isPlausibleHost(referral) && !net.isIP(referral) && referral !== "whois.iana.org") {
102	      try {
103	        const registryText = await whoisQuery(referral, host);
104	        if (registryText.trim().length > 0) {
105	          text = registryText;
106	          server = referral;
107	        }
108	      } catch {
109	        /* fall back to the IANA body */
110	      }
111	    }
112	
113	    if (!text.trim()) return jsonError("No WHOIS data returned for that domain.", 404);
114	
115	    return NextResponse.json({
116	      ok: true,
117	      host,
118	      server,
119	      summary: summarize(text),
120	      raw: text.slice(0, MAX_BYTES),
121	    });
122	  } catch (e) {
123	    const msg = e instanceof Error ? e.message : "WHOIS lookup failed.";
124	    return jsonError(msg, 502);
125	  }
126	}
