32	  return NextResponse.json({
33	    ok: true,
34	    ip,
35	    version: kind === 4 ? "IPv4" : kind === 6 ? "IPv6" : "unknown",
36	    reverseDns: ptr,
37	    userAgent: (req.headers.get("user-agent") ?? "").slice(0, 400) || null,
38	    forwardedFor: req.headers.get("x-forwarded-for") ?? null,
