1	import { NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { jsonError, toolRateLimit } from "@/lib/tools/api";
4	import { aiAvailable, aiCandidates } from "@/lib/tools/domain-ai";
5	import { checkAvailabilityBatched, type DomainResult } from "@/lib/tools/domain-availability";
6	import { generateCandidates, type Candidate } from "@/lib/tools/domain-generate";
7	import { ALLOWED_TLDS, DEFAULT_TLDS, TONES, type Tone } from "@/lib/tools/domain-vocab";
8	
9	export const runtime = "nodejs";
10	export const dynamic = "force-dynamic";
11	
12	/**
13	 * AI domain-name generator — public, unauthenticated, and therefore capped hard.
14	 *
15	 * Cost controls, in order of defence:
16	 *   1. Two per-IP sliding windows (burst + hourly) via the shared tool limiter.
17	 *   2. MAX_NAMES caps how many labels we generate, so at most ONE Claude call
18	 *      with a fixed `max_tokens` per accepted request.
19	 *   3. MAX_LOOKUPS caps registrar volume per request; the lookups are batched
20	 *      into a single upstream call and cached for 10 minutes, and a process-wide
21	 *      window in `domain-availability.ts` guards the shared registrar budget.
22	 *
23	 * Degradation: no ANTHROPIC_API_KEY (or any Claude failure) falls back to the
24	 * local heuristic generator; a registrar failure marks names "unknown" rather
25	 * than claiming they're free. Neither is surfaced to the visitor as an error.
26	 */
27	
28	/** Distinct name ideas per request. */
29	const MAX_NAMES = 12;
30	
31	/** Absolute ceiling on registrar lookups per request (names x TLDs). */
32	const MAX_LOOKUPS = 24;
33	
34	/** TLDs a visitor may select at once. */
35	const MAX_TLDS = 3;
36	
37	const MAX_IDEA_LEN = 400;
38	const MAX_KEYWORDS_LEN = 120;
39	
40	const VALID_TONES = new Set(TONES.map((t) => t.value));
41	
42	type Body = { idea?: unknown; keywords?: unknown; tone?: unknown; tlds?: unknown };
43	
44	function readString(v: unknown, max: number): string {
45	  return typeof v === "string" ? v.replace(/\s+/g, " ").trim().slice(0, max) : "";
46	}
47	
48	function readTlds(v: unknown): string[] {
49	  if (!Array.isArray(v)) return DEFAULT_TLDS;
50	  const out: string[] = [];
51	  for (const raw of v) {
52	    if (typeof raw !== "string") continue;
53	    const tld = raw.toLowerCase().replace(/^\./, "").trim();
54	    if (ALLOWED_TLDS.has(tld) && !out.includes(tld)) out.push(tld);
55	    if (out.length >= MAX_TLDS) break;
56	  }
57	  return out.length ? out : DEFAULT_TLDS;
58	}
59	
60	/**
61	 * Pair labels with TLDs, TLD-major, capped at MAX_LOOKUPS. TLD-major means the
62	 * visitor's first-choice extension is checked for every name before we spend any
63	 * budget on the second choice.
64	 */
65	function buildDomains(candidates: Candidate[], tlds: string[]): string[] {
66	  const domains: string[] = [];
67	  for (const tld of tlds) {
68	    for (const c of candidates) {
69	      if (domains.length >= MAX_LOOKUPS) return domains;
70	      domains.push(`${c.sld}.${tld}`);
71	    }
72	  }
73	  return domains;
74	}
75	
76	export async function POST(req: Request) {
77	  // Burst limit, then a longer window so a single IP can't grind all day.
78	  const burst = toolRateLimit(req, "domain-generator", { max: 6, windowMs: 60_000 });
79	  if (burst) return burst;
80	  const hourly = toolRateLimit(req, "domain-generator-hourly", { max: 40, windowMs: 60 * 60_000 });
81	  if (hourly) return hourly;
82	
83	  const body = (await req.json().catch(() => ({}))) as Body;
84	  const idea = readString(body.idea, MAX_IDEA_LEN);
85	  const keywords = readString(body.keywords, MAX_KEYWORDS_LEN);
86	  const toneRaw = readString(body.tone, 20);
87	  const tone: Tone = VALID_TONES.has(toneRaw as Tone) ? (toneRaw as Tone) : "any";
88	  const tlds = readTlds(body.tlds);
89	
90	  if (idea.length < 8) {
91	    return jsonError("Describe your business or idea in a few words (at least 8 characters).");
92	  }
93	
94	  // 1) Names — Claude when the platform key is set, heuristics otherwise.
95	  let candidates: Candidate[] | null = null;
96	  let source: "ai" | "heuristic" = "heuristic";
97	  if (aiAvailable()) {
98	    candidates = await aiCandidates({ idea, keywords, tone, count: MAX_NAMES });
99	    if (candidates && candidates.length) source = "ai";
100	  }
101	  if (!candidates || candidates.length < MAX_NAMES) {
102	    const local = generateCandidates({ idea, keywords, tone, limit: MAX_NAMES });
103	    const merged = candidates ? [...candidates] : [];
104	    const seen = new Set(merged.map((c) => c.sld));
105	    for (const c of local) {
106	      if (merged.length >= MAX_NAMES) break;
107	      if (seen.has(c.sld)) continue;
108	      seen.add(c.sld);
109	      merged.push(c);
110	    }
111	    candidates = merged;
112	  }
113	
114	  if (!candidates.length) {
115	    return jsonError("We couldn't build names from that description — try adding a little more detail.");
116	  }
117	
118	  const byLabel = new Map(candidates.map((c) => [c.sld, c]));
119	
120	  // 2) Availability — one batched, cached registrar call.
121	  const domains = buildDomains(candidates, tlds);
122	  const availability = await checkAvailabilityBatched(domains);
123	
124	  const results = availability.results.map((r: DomainResult) => {
125	    const sld = r.domain.slice(0, r.domain.lastIndexOf("."));
126	    const tld = r.domain.slice(r.domain.lastIndexOf(".") + 1);
127	    const meta = byLabel.get(sld);
128	    return {
129	      domain: r.domain,
130	      sld,
131	      tld,
132	      status: r.status,
133	      premium: r.premium,
134	      priceCents: r.priceCents,
135	      renewCents: r.renewCents,
136	      style: meta?.style ?? "invented",
137	      note: meta?.note ?? "",
138	    };
139	  });
140	
141	  // Available first (cheapest first within that), then unknown, then taken.
142	  const rank = { available: 0, unknown: 1, taken: 2 } as const;
143	  results.sort(
144	    (a, b) =>
145	      rank[a.status] - rank[b.status] ||
146	      (a.priceCents ?? Number.MAX_SAFE_INTEGER) - (b.priceCents ?? Number.MAX_SAFE_INTEGER) ||
147	      a.domain.length - b.domain.length,
148	  );
149	
150	  // Signed-in visitors go straight into the pre-filled registration wizard;
151	  // everyone else lands on signup with the name carried through.
152	  let signedIn = false;
153	  try {
154	    signedIn = Boolean(await currentUser());
155	  } catch {
156	    /* session lookup unavailable — treat as anonymous */
157	  }
158	
159	  return NextResponse.json({
160	    ok: true,
161	    source,
162	    signedIn,
163	    registrarConfigured: availability.configured,
164	    throttled: availability.throttled,
165	    checked: results.length,
166	    tlds,
167	    results,
168	  });
169	}
