import { NextResponse } from "next/server";
import net from "node:net";
import { checkRateLimit } from "@/lib/rate-limit";

/**
 * Trustworthy client-IP extraction for the public HTTP API.
 *
 * ─────────────────────────────────────────────────────────────────────────────
 * WHY THIS EXISTS — the bug it fixes
 * ─────────────────────────────────────────────────────────────────────────────
 * Every route in `app/api/**` used to carry a private copy of:
 *
 *     const xff = req.headers.get("x-forwarded-for") ?? "";
 *     return xff.split(",")[0]?.trim() || "unknown";     // ← FIRST hop
 *
 * with the comment "first hop of x-forwarded-for is the real client (nginx
 * appends downstream)". That comment is backwards, and it made every per-IP
 * rate limit on this platform a no-op.
 *
 * All Nxeon vhosts (`/etc/nginx/sites-available/nxeon*`, generated by
 * `scripts/configure-domains.sh`) proxy with:
 *
 *     proxy_set_header X-Real-IP        $remote_addr;
 *     proxy_set_header X-Forwarded-For  $proxy_add_x_forwarded_for;
 *
 * `$proxy_add_x_forwarded_for` is defined as "the client's X-Forwarded-For
 * header, with $remote_addr APPENDED to it". So for a request that arrives
 * carrying `X-Forwarded-For: 203.0.113.77`, the app receives:
 *
 *     X-Forwarded-For: 203.0.113.77, <the real peer address>
 *                      ^^^^^^^^^^^^  attacker-chosen, and what we were keying on
 *
 * Verified live against production through nginx on 2026-07-27:
 *   curl -H 'X-Forwarded-For: 203.0.113.77' https://nxeon.cloud/api/tools/my-ip
 *   → {"ip":"203.0.113.77", "forwardedFor":"203.0.113.77, 127.0.0.1"}
 *
 * Consequence: rotating one header per request gave an unauthenticated attacker
 * an unlimited budget on every throttled endpoint — unbounded row insertion via
 * /api/track and /api/chat, unbounded 5 MB blobs via /api/chat/upload, unbounded
 * outbound scanning via /api/tools/port-checker, and unbounded spend on the
 * platform Claude key and the registrar via /api/tools/domain-generator.
 *
 * ─────────────────────────────────────────────────────────────────────────────
 * WHAT IS ACTUALLY TRUSTWORTHY
 * ─────────────────────────────────────────────────────────────────────────────
 * Only values nginx itself writes:
 *
 *   1. `X-Real-IP` — set unconditionally from `$remote_addr`. `proxy_set_header`
 *      REPLACES any client-supplied value, so this is a single, unforgeable
 *      address. Preferred.
 *   2. The LAST hop of `X-Forwarded-For` — the segment nginx appended. A client
 *      can prepend as many fake hops as it likes; it can never append after
 *      nginx. Used when `X-Real-IP` is missing.
 *
 * Anything else (the first hop, the whole header, a body-supplied IP) is
 * attacker-controlled and must never key a rate limit, an audit row, or an
 * abuse decision.
 *
 * NOTE — deployment coupling: this is correct for exactly ONE reverse proxy in
 * front of the app, which is the current topology (nginx → :3000 / :3001, and
 * :3000 is not reachable from the internet). If a CDN or a second proxy is ever
 * added, the trusted value becomes "the hop N from the right", and this helper
 * must be updated with it — the fix is not to go back to reading the first hop.
 */

/** `unknown` is the shared bucket for callers we cannot place. */
export const UNKNOWN_IP = "unknown";

/**
 * The client address as attested by our own reverse proxy.
 *
 * Never returns a client-controlled value. Falls back to `UNKNOWN_IP` when no
 * proxy header is present (direct-to-port access, which is not internet-facing)
 * so that such callers share one conservative bucket rather than each getting a
 * private one.
 */
export function trustedClientIp(req: Request): string {
  // 1. X-Real-IP — nginx overwrites this unconditionally.
  const real = req.headers.get("x-real-ip")?.trim();
  if (real && net.isIP(stripPort(real)) !== 0) return stripPort(real);

  // 2. Last hop of X-Forwarded-For — the segment nginx appended.
  const xff = req.headers.get("x-forwarded-for") ?? "";
  const hops = xff
    .split(",")
    .map((h) => h.trim())
    .filter(Boolean);
  for (let i = hops.length - 1; i >= 0; i--) {
    const candidate = stripPort(hops[i]);
    if (net.isIP(candidate) !== 0) return candidate;
  }

  return UNKNOWN_IP;
}

/**
 * Strip an optional `:port` / `[v6]:port` wrapper and an IPv4-mapped IPv6
 * prefix so the same peer always produces the same bucket key.
 */
function stripPort(value: string): string {
  let v = value.trim();
  if (v.startsWith("[")) {
    const end = v.indexOf("]");
    if (end !== -1) v = v.slice(1, end);
  } else if (v.includes(":") && net.isIP(v) === 0) {
    // host:port for IPv4 (a bare IPv6 has many colons and parses as an IP).
    v = v.split(":")[0];
  }
  // ::ffff:127.0.0.1 and 127.0.0.1 are the same peer — normalise to the IPv4.
  const mapped = /^::ffff:((?:\d{1,3}\.){3}\d{1,3})$/i.exec(v);
  if (mapped) return mapped[1];
  return v;
}

/**
 * Per-IP throttle for a named public tool, keyed on the PROXY-ATTESTED address.
 *
 * Mirrors `toolRateLimit` in `lib/tools/api.ts` (same key shape, same response)
 * but sources the IP from `trustedClientIp` instead of the spoofable first hop.
 * The `lib/` original is left untouched deliberately — see the audit report; it
 * should be collapsed into this one once `lib/` is editable again.
 */
export function toolRateLimitByIp(
  req: Request,
  tool: string,
  opts: { max?: number; windowMs?: number } = {},
): NextResponse | null {
  const { max = 20, windowMs = 60_000 } = opts;
  const rl = checkRateLimit(`tool:${tool}:${trustedClientIp(req)}`, { max, windowMs });
  if (!rl.ok) {
    return NextResponse.json(
      { ok: false, error: `Rate limit reached. Try again in ${rl.retryAfterSec}s.` },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } },
    );
  }
  return null;
}

