import { NextResponse } from "next/server";
import net from "node:net";
import { Agent } from "undici";
import { jsonError, readField } from "@/lib/tools/api";
import { toolRateLimitByIp } from "@/app/api/_lib/client-ip";
import { resolvePublicHost, BlockedHostError } from "@/lib/tools/net-guard";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * HTTP header inspector — fetches a URL and returns the status + response headers.
 *
 * SSRF guard, in layers:
 *   1. Only http/https schemes.
 *   2. `resolvePublicHost` resolves the host and rejects if ANY resolved address
 *      is private / loopback / link-local / reserved.
 *   3. The connection is PINNED to an address vetted in step 2 (see
 *      `pinnedAgent`), so the name is never resolved a second time.
 *   4. Redirects are NOT followed (`redirect: "manual"`) — we only report the
 *      Location header, so we can't be bounced to an internal endpoint.
 *   5. 5s timeout, header values capped, the body is never read.
 *
 * Step 3 used to be missing, and steps 2 and 4 do not cover the gap it left.
 * `resolvePublicHost(url.hostname)` was called for its throw-or-don't side
 * effect and its returned `addresses` were discarded; the fetch that followed
 * was handed the HOSTNAME, so the runtime resolved it AGAIN on the way out.
 * That is a textbook DNS-rebinding window: an attacker points a name they
 * control at a public IP with a 0-second TTL, we check it and approve it, and
 * by the time undici opens the socket the same name answers 127.0.0.1. The
 * request then leaves from inside the trust boundary — Proxmox on
 * 127.0.0.1:8006, the app itself on :3000, anything on the 10.20.0.0/24 VM
 * bridge — and we hand the caller back its status line and every response
 * header. `resolvePublicHost` returns `addresses` precisely so callers can
 * close this; port-checker and ssl-checker already did, this route did not.
 */

const TIMEOUT_MS = 5000;

/**
 * An undici Agent whose DNS resolution is hard-wired to an already-vetted
 * address. Host and SNI still come from the URL, so virtual hosts and TLS
 * certificate validation behave normally — only the address we dial is fixed.
 */
function pinnedAgent(address: string): Agent {
  return new Agent({
    connect: {
      lookup: (
        _hostname: string,
        _options: unknown,
        callback: (err: Error | null, addr: string, family: number) => void,
      ) => callback(null, address, net.isIP(address)),
    },
  });
}

